    {'text': 'Broadband internet restore ho gaya hai, speed testing me 200 Mbps aa rahi hai.', 'label': 0, 'scam_type': 'benign', 'language': 'hi-en', 'source': 'curated_multilingual_indian_corpus', 'source_group': 'hien_grp_014', 'is_synthetic': False, 'original_id': 'IND_HIEN_0130', 'provenance': 'curated_multilingual_indian_corpus'},
    {'text': 'வணக்கம், நாளை காலை 10 மணிக்கு அலுவலகத்தில் குழு கூட்டம் உள்ளது.', 'label': 0, 'scam_type': 'benign', 'language': 'ta', 'source': 'curated_multilingual_indian_corpus', 'source_group': 'ta_grp_001', 'is_synthetic': False, 'original_id': 'IND_TA_0131', 'provenance': 'curated_multilingual_indian_corpus'},
    {'text': 'வணக்கம், திட்ட மதிப்பாய்வு கூட்டம் நாளை காலை 10:00 மணிக்கு நடைபெறும்.', 'label': 0, 'scam_type': 'benign', 'language': 'ta', 'source': 'curated_multilingual_indian_corpus', 'source_group': 'ta_grp_001', 'is_synthetic': False, 'original_id': 'IND_TA_0132', 'provenance': 'curated_multilingual_indian_corpus'},
    {'text': 'அனைவரும் நாளை காலை 10 மணிக்கு கூட்ட அரங்கில் கூடுமாறு கேட்டுக்கொள்ளப்படுகிறார்கள்.', 'label': 0, 'scam_type': 'benign', 'language': 'ta', 'source': 'curated_multilingual_indian_corpus', 'source_group': 'ta_grp_001', 'is_synthetic': False, 'original_id': 'IND_TA_0133', 'provenance': 'curated_multilingual_indian_corpus'},
    {'text': 'நாளை காலை 10 மணிக்கு நடைபெறும் கூட்டத்திற்கான ஆவணங்கள் பகிரப்பட்டுள்ளன.', 'label': 0, 'scam_type': 'benign', 'language': 'ta', 'source': 'curated_multilingual_indian_corpus', 'source_group': 'ta_grp_001', 'is_synthetic': False, 'original_id': 'IND_TA_0134', 'provenance': 'curated_multilingual_indian_corpus'},
    {'text': 'வணக்கம், நாளை காலை 10 மணி கூட்டம் குறித்த விவரங்களை சரிபார்க்கவும்.', 'label': 0, 'scam_type': 'benign', 'language': 'ta', 'source': 'curated_multilingual_indian_corpus', 'source_group': 'ta_grp_001', 'is_synthetic': False, 'original_id': 'IND_TA_0135', 'provenance': 'curated_multilingual_indian_corpus'},
    {'text': 'அம்மா, நான் அலுவலகத்தில் இருந்து கிளம்பிவிட்டேன், 8 மணிக்கு வீடு திரும்புவேன்.', 'label': 0, 'scam_type': 'benign', 'language': 'ta', 'source': 'curated_multilingual_indian_corpus', 'source_group': 'ta_grp_002', 'is_synthetic': False, 'original_id': 'IND_TA_0136', 'provenance': 'curated_multilingual_indian_corpus'},
    {'text': 'அம்மா, வழியில் சிறிது போக்குவரத்து நெரிசல் உள்ளது, 8:15க்குள் வந்துவிடுவேன்.', 'label': 0, 'scam_type': 'benign', 'language': 'ta', 'source': 'curated_multilingual_indian_corpus', 'source_group': 'ta_grp_002', 'is_synthetic': False, 'original_id': 'IND_TA_0137', 'provenance': 'curated_multilingual_indian_corpus'},
